// SolidBulkUploadPage.js
import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

/* ============================================================
   PARTICLES (ManageEvaluationTasksPage Style)
============================================================ */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);

    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

/* ============================================================
   MAIN PAGE — BULK UPLOAD FOR SOLID
============================================================ */
function SolidBulkUploadPage() {
    const { studyId } = useParams();
    const navigate = useNavigate();

    const [study, setStudy] = useState(null);
    const [file, setFile] = useState(null);
    const [processing, setProcessing] = useState(false);
    const [progress, setProgress] = useState(0);
    const [done, setDone] = useState(false);

    /* FETCH STUDY INFO (sadece başlık vs göstermek istersen şimdilik optional) */
    useEffect(() => {
        fetch(`http://localhost:8080/api/studies/${studyId}`)
            .then((r) => r.json())
            .then((d) => setStudy(d))
            .catch(console.error);
    }, [studyId]);

    const handleFileChange = (e) => {
        setFile(e.target.files[0]);
        setDone(false);
        setProgress(0);
    };

    /* ============================================================
       MAIN BULK UPLOAD PROCESS (TEK REQUEST → /api/bulk/solid/{id})
    ============================================================ */
    const handleUpload = async () => {
        if (!file) {
            alert("Please select a JSON file.");
            return;
        }

        const token = localStorage.getItem("token");
        if (!token) {
            alert("You must be logged in.");
            return;
        }

        try {
            setProcessing(true);
            setProgress(5);

            const text = await file.text();

            let parsed;
            try {
                parsed = JSON.parse(text);
            } catch (e) {
                console.error("Invalid JSON:", e);
                alert("Invalid JSON file format.");
                setProcessing(false);
                setProgress(0);
                return;
            }

            // DTO ile uyumlu payload:
            // SolidDatasetDTO: { "code_examples": [ {input, output, level, language, violation}, ... ] }
            let payload;
            if (Array.isArray(parsed)) {
                // Eğer dosya direkt array ise
                payload = { code_examples: parsed };
            } else if (parsed.code_examples) {
                payload = parsed;
            } else {
                alert('JSON must have a "code_examples" array.');
                setProcessing(false);
                setProgress(0);
                return;
            }

            setProgress(25);

            const response = await fetch(
                `http://localhost:8080/api/bulk/solid/${studyId}`,
                {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": `Bearer ${token}`,
                    },
                    body: JSON.stringify(payload),
                }
            );

            if (!response.ok) {
                const err = await response.json().catch(() => ({}));
                console.error("Bulk upload error:", err);
                alert("Bulk upload failed: " + (err.error || response.status));
                setProcessing(false);
                setProgress(0);
                return;
            }

            const result = await response.json();
            console.log("Bulk result:", result);

            setProgress(100);
            setDone(true);
        } catch (err) {
            console.error("Unexpected error in bulk upload:", err);
            alert("Unexpected error during bulk upload. Check console.");
            setProgress(0);
        } finally {
            setProcessing(false);
        }
    };

    useEffect(() => {
        if (done && progress === 100) {
            const timer = setTimeout(() => {
                navigate(`/manage-tasks/${studyId}`);
            }, 1200);

            return () => clearTimeout(timer);
        }
    }, [done, progress, navigate, studyId]);

    return (
        <div style={styles.container}>
            <FloatingParticles />

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>📦 Bulk Upload — SOLID Detection</h2>

                <button
                    style={styles.backButton}
                    onClick={() => navigate(`/manage-tasks/${studyId}`)}
                >
                    ← Back
                </button>
            </div>

            {/* WRAPPER */}
            <div style={styles.wrapper}>
                <div style={styles.card}>
                    <h3 style={styles.title}>Upload JSON File (code_examples list)</h3>

                    <label style={styles.uploadBox}>
                        <input
                            type="file"
                            accept=".json"
                            style={{ display: "none" }}
                            onChange={handleFileChange}
                        />
                        {file ? (
                            <span>📄 {file.name}</span>
                        ) : (
                            <span>Select JSON File</span>
                        )}
                    </label>

                    {/* Upload Button */}
                    <button
                        style={styles.uploadButton}
                        disabled={!file || processing}
                        onClick={handleUpload}
                    >
                        {processing ? "Processing..." : "Start Bulk Upload"}
                    </button>

                    {/* PROGRESS */}
                    {(processing || done) && (
                        <>
                            <div style={styles.progressBackground}>
                                <div
                                    style={{
                                        ...styles.progressFill,
                                        width: `${progress}%`,
                                    }}
                                />
                            </div>
                            <p style={styles.progressLabel}>{progress}%</p>
                        </>
                    )}

                    {done && (
                        <p style={styles.doneMessage}>
                            ✔ All artifacts & tasks created successfully!
                        </p>
                    )}
                </div>
            </div>

            <style>
                {`
                @keyframes floatParticle {
                    0% { transform: translateY(0); opacity: .4; }
                    50% { opacity: 1; }
                    100% { transform: translateY(-120vh); opacity: 0; }
                }
                `}
            </style>
        </div>
    );
}

/* ============================================================
   STYLES
============================================================ */
const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0a0a0a, #16213e)",
        color: "#fff",
        fontFamily: "Inter, sans-serif",
        overflow: "hidden",
        position: "relative",
    },
    particles: {
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none",
        zIndex: 0,
    },
    particle: {
        position: "absolute",
        width: "4px",
        height: "4px",
        background: "linear-gradient(135deg, #06b6d4, #8b5cf6)",
        borderRadius: "50%",
        animation: "floatParticle linear infinite",
        opacity: 0.45,
    },
    navbar: {
        display: "flex",
        justifyContent: "space-between",
        padding: "20px 40px",
        background: "rgba(255,255,255,0.03)",
        borderBottom: "1px solid rgba(255,255,255,0.1)",
    },
    navTitle: {
        fontSize: "1.5rem",
        fontWeight: "700",
        color: "#60a5fa",
    },
    backButton: {
        background: "rgba(220,38,38,0.15)",
        border: "2px solid rgba(220,38,38,0.55)",
        color: "#fca5a5",
        padding: "8px 20px",
        borderRadius: "10px",
        cursor: "pointer",
        fontWeight: "600",
        boxShadow: "0 0 12px rgba(220,38,38,0.35)",
        transition: "0.2s ease",
    },
    wrapper: {
        width: "90%",
        maxWidth: "600px",
        margin: "40px auto",
    },
    card: {
        background: "rgba(255,255,255,0.05)",
        padding: "30px",
        borderRadius: "18px",
        border: "1px solid rgba(255,255,255,0.12)",
        textAlign: "center",
        boxShadow: "0 0 20px rgba(0,0,0,0.3)",
    },
    title: {
        fontSize: "1.3rem",
        fontWeight: "700",
        marginBottom: "20px",
    },
    uploadBox: {
        display: "flex",
        alignItems: "center",
        justifyContent: "center",

        width: "100%",
        maxWidth: "100%",  // taşmayı tamamen engeller

        padding: "20px",

        borderRadius: "12px",
        border: "2px dashed rgba(255,255,255,0.25)",

        boxSizing: "border-box", // 🔥 Tüm taşma sorunlarının çözümü
        overflow: "hidden",       // ekstra güvenlik
        background: "rgba(255,255,255,0.03)",

        cursor: "pointer",
        marginBottom: "20px",
    },
    uploadButton: {
        width: "100%",
        padding: "14px",
        borderRadius: "12px",
        background: "linear-gradient(135deg, #10b981, #059669)",
        color: "white",
        fontWeight: "700",
        border: "none",
        cursor: "pointer",
        marginBottom: "20px",
        transition: "0.25s",
    },
    progressBackground: {
        width: "100%",
        height: "12px",
        background: "rgba(255,255,255,0.10)",
        borderRadius: "10px",
        marginTop: "10px",
    },
    progressFill: {
        height: "100%",
        background: "linear-gradient(135deg, #3b82f6, #60a5fa)",
        borderRadius: "10px",
        transition: "width 0.3s ease",
    },
    progressLabel: {
        marginTop: "8px",
        fontSize: "0.9rem",
        color: "#cbd5e1",
    },
    doneMessage: {
        marginTop: "15px",
        fontSize: "1rem",
        color: "#6ee7b7",
        fontWeight: "700",
    },
};
export default SolidBulkUploadPage;
